if (isArt) {
  var d = typeof result === 'string' ? JSON.parse(result) : result;
  var obj = (d && d.list) ? d.list[0] : {};
  var html = obj.art_content || obj.art_pic || '';
  var imgs = html.match(/https?:\/\/[^\s"'<>]+\.(?:jpg|jpeg|png|gif|webp)/gi);
  if (imgs && imgs.length > 0) {
    out = imgs.map(function(u){return '<img src="' + u + '">';}).join('\n');
  } else {
    out = html.replace(/\n/g, '<br>');
  }
}
