@js:(function() {
  var doc = org.jsoup.Jsoup.parse(result);
  var items = [];
  var rows = doc.select('p.sone');
  if (rows.size() === 0) return [];
  for (var i = 0; i < rows.size(); i++) {
    var row = rows.get(i);
    var a = row.selectFirst('a');
    if (!a) continue;
    var text = a.text().trim();
    var name = text.indexOf('/') !== -1 ? text.split('/')[0].trim() : text;
    var url = a.attr('href');
    var authorSpan = row.selectFirst('span.author a');
    var author = authorSpan ? authorSpan.text().trim() : '';
    items.push({
      name: name,
      url: url,
      author: author
    });
  }
  return items;
})();

